import asyncio
import json
import uuid
from datetime import datetime
from threading import Lock
from typing import Dict, Set

import websockets
from aiohttp import web


class NotificationServer:
    """Thread-safe WebSocket notification server."""

    def __init__(self):
        self.clients: Dict[str, websockets.ServerConnection] = {}
        self.lock = Lock()

    def add_client(self, client_id: str, websocket) -> None:
        """Add a client to the registry."""
        with self.lock:
            self.clients[client_id] = websocket

    def remove_client(self, client_id: str) -> None:
        """Remove a client from the registry."""
        with self.lock:
            self.clients.pop(client_id, None)

    def get_client_count(self) -> int:
        """Get the number of connected clients."""
        with self.lock:
            return len(self.clients)

    def get_all_clients(self) -> Dict[str, websockets.ServerConnection]:
        """Get a snapshot of all clients."""
        with self.lock:
            return self.clients.copy()

